/* Second generation data. All art is generated by pixel.js; no first-generation images. */
(() => {
  const add = (id, side, name, color, accent, desc, roster, theme, bonus) => {
    const source = CIVS[side === 'hk' ? 'hk_police' : 'zom_classic'];
    const units = {};
    roster.forEach(([key,label,tier,arch,extra={}],i) => {
      const ranged = /ranged|support|cata/.test(arch);
      const tank = /tank|giant/.test(arch);
      const costs=[55,180,560,1200];
      units[key] = U(label,costs[tier-1],tank?3:(tier>2?3:1),tank?[180,220,300,520][tier-1]:[55,80,145,280][tier-1],[11,23,32,50][tier-1],arch==='zom_cata'?360:ranged?210:28,tank?32:52,ranged?1.35:0.95,1.5+tier*.6,[null,B.TECH_A,B.TECH_B,B.TECH_C][tier-1],arch,{desc:extra.desc || `${name}的${label}。${ranged?'远程支援':'前线作战'}单位。`,...extra});
    });
    CIVS[id]={id,side,name,color,accent,desc,theme,bonus,baseIncome:5.5,baseCap:24,baseRegen:3,buildings:JSON.parse(JSON.stringify(source.buildings)),units,skills:[]};
    CIVS[id].skills=Array.from({length:3},(_,i)=>id+'_skill_'+i);
  };
  add('hk_university','hk','香港大学城','#46bab9','#a2f4dd','科研、急救与自动化防线。采集效率 +12%。',[
    ['student','校园守卫',1,'melee_cheap'],['medic','急救研究员',2,'support',{support:'heal',healAmt:30}],['engineer','工程系射手',2,'ranged_light'],['drone','巡防无人机',3,'ranged_heavy',{machine:true}],['exo','外骨骼教授',3,'melee_tank',{machine:true}],['mortar','电磁迫击炮',3,'zom_cata',{lobber:true,machine:true}],['sentinel','城大守望机甲',4,'ranged_heavy',{splash:36,machine:true}]
  ],'university','gather');
  add('hk_wild','hk','港氏野人帮','#b8a56b','#f3d49a','中世纪部族、盾墙与重型投石。民房便宜25%。',[
    ['club','木棒民兵',1,'melee_cheap'],['archer','长弓猎手',2,'ranged_light'],['pike','长枪卫士',2,'melee_cheap'],['knight','铁甲斧卫',3,'melee_tank'],['shaman','山城祭司',3,'support',{support:'heal',healAmt:34}],['trebuchet','重型投石机',3,'zom_cata',{lobber:true,machine:true}],['warlord','港氏战王',4,'melee_tank',{splash:42}]
  ],'medieval','housing');
  add('hk_gang','hk','香港黑帮','#a784c4','#efbadb','霓虹街头的刀手、枪手与改装车。训练速度 +15%。',[
    ['blade','街头刀手',1,'melee_fast'],['pistol','堂口枪手',2,'ranged_light'],['fire','燃瓶打手',2,'ranged_aoe',{splash:30}],['enforcer','红棍打手',3,'melee_tank'],['tommy','冲锋枪手',3,'ranged_heavy'],['van','改装战车',3,'ranged_heavy',{machine:true,splash:25}],['boss','九龙龙头',4,'ranged_ceo']
  ],'gang','training');
  add('zom_robot','zom','AI机器人僵尸','#758fbc','#94d9fd','被感染的自治机械。全军消耗木头与黄金。',[
    ['scrap','废铁行尸',1,'zom_normal',{machine:true}],['crawler','机械爬行者',2,'zom_hopper',{machine:true,jump:110}],['laser','镭射尸兵',2,'ranged_light',{machine:true}],['bulwark','装甲屠夫',3,'zom_giant',{machine:true}],['rail','轨道炮台',3,'ranged_heavy',{machine:true}],['fabricator','修复节点',3,'support',{support:'heal',healAmt:38,machine:true}],['titan','失控主脑',4,'zom_giant',{machine:true,splash:48}]
  ],'robot','machine');
  add('zom_necro','zom','尸变体','#ae7869','#ffc293','骨刃、重组组织与寄生孢群。前线再生 +1生命/秒。',[
    ['slasher','裂骨者',1,'zom_normal'],['leaper','肢节跃兽',2,'zom_hopper',{jump:125}],['spine','骨刺喷射者',2,'ranged_aoe',{splash:22}],['brute','重组暴君',3,'zom_giant'],['burst','囊肿爆破者',3,'zom_toxic',{onDeath:'explode',explodeDmg:150,explodeR:70}],['sower','寄生播种者',3,'support',{support:'convert',dur:4.5}],['hive','群巢母骸',4,'zom_giant',{aura:'heal',auraR:130,auraAmt:6,splash:40}]
  ],'necro','regen');
  add('zom_asym','zom','非对称怪物','#858a70','#d9e799','不对称肢体与巨大轮廓。巨型近战生命 +12%。',[
    ['crooked','歪斜人',1,'zom_normal'],['longarm','长臂捕手',2,'zom_banshee'],['watcher','独眼凝视者',2,'ranged_light'],['crusher','偏肢巨兽',3,'zom_giant'],['howler','裂口嚎叫者',3,'ranged_aoe',{splash:35}],['mirror','反向寄生体',3,'support',{support:'convert',dur:5}],['colossus','超巨畸形体',4,'zom_giant',{splash:65}]
  ],'asym','giant');
  SKILLS.capital_injection.desc='立即获得1200黄金，农民采集效率 +12.5%，持续45秒。';
  const themes=['finance','street','police','classic','ghost','bio'];
  Object.values(CIVS).forEach((c,index)=>{
    c.theme ||= themes[index];
    c.baseCap = 24 + (c.id==='hk_slum'||c.id==='zom_ghost'?8:0);
    c.buildings[B.POP].effect.pop=50;
    c.buildings[B.POP].cap=12;
    c.buildings.castle={name:'防御城堡',cost:250,cap:2,hp:1300,effect:{}};
    Object.entries(c.units).forEach(([id,u],i)=>{
      u.tier = !u.prereq?1:u.prereq===B.TECH_A?2:u.prereq===B.TECH_B?3:4;
      u.machine ||= !!u.lobber || /truck|rickshaw|van|drone|exo|mortar|sentinel|trebuchet/.test(id);
      u.art={theme:c.theme,index:i,variant:index,tier:u.tier,arch:u.arch,machine:!!u.machine};
      // Economy and combat profiles are applied once by balance.js.
    });
  });
  window.HK_CIVS=Object.keys(CIVS).filter(id=>CIVS[id].side==='hk');
  window.ZOM_CIVS=Object.keys(CIVS).filter(id=>CIVS[id].side==='zom');
})();
